arguments.command:
printf '#!/bin/sh
case "$1" in
 *Username*) echo x-access-token;;
 *Password*) echo "$GITHUB_TOKEN";;
esac
' > /tmp/askpass.sh && chmod +x /tmp/askpass.sh && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/friend-phoebe-wt3 -c credential.helper= push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5 && git -C /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill fetch origin friend/phoebe && git -C /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill log --oneline -2 origin/friend/phoebe
